// =================================================================
// DIL / LANGUAGE (TR / EN) - localStorage'da saklanir (gcs_dil)
// ---------------------------------------------------------------
const DIL_KEY = "gcs_dil";
let aktifDil = (function(){
  try {
    const d = localStorage.getItem(DIL_KEY);
    return (d === "EN" || d === "TR") ? d : "TR";
  } catch(e){ return "TR"; }
})();

