function D(){ return DILLER[aktifDil] || DILLER.TR; }

function applyLanguage(dil, kaydet){
  if (dil !== "TR" && dil !== "EN") return;
  aktifDil = dil;
  if (kaydet){
    try { localStorage.setItem(DIL_KEY, dil); } catch(e){}
  }
  const t = D();
  // data-i18n isaretli statik elemanlar
  document.querySelectorAll("[data-i18n]").forEach(el => {
    const k = el.dataset.i18n;
    if (t[k] !== undefined) el.textContent = t[k];
  });
  // NOT: ikonlu butonlarda data-i18n ic <span>'dedir; textContent yalniz
  // span'i degistirir, buton basindaki <i> ikonu korunur.

  // v2.4.34: NITELIK CEVIRISI.
  // Ikon butonlarinin `title` ipuclari ve form alanlarinin
  // `placeholder` metinleri textContent'te olmadigi icin yukaridaki
  // dongu bunlari kapsamiyordu; EN'e gecildiginde Turkce kaliyorlardi.
  // Artik data-i18n-title / data-i18n-ph / data-i18n-aria ile cevrilir.
  document.querySelectorAll("[data-i18n-title]").forEach(el => {
    const k = el.dataset.i18nTitle;
    if (t[k] !== undefined) el.setAttribute("title", t[k]);
  });
  document.querySelectorAll("[data-i18n-ph]").forEach(el => {
    const k = el.dataset.i18nPh;
    if (t[k] !== undefined) el.setAttribute("placeholder", t[k]);
  });
  document.querySelectorAll("[data-i18n-aria]").forEach(el => {
    const k = el.dataset.i18nAria;
    if (t[k] !== undefined) el.setAttribute("aria-label", t[k]);
  });
  // Ozel statik elemanlar (YKI basligi artik data-i18n=panelYki ile cevrilir)
  // v2.4.33: #ipucuMetin (RFD900X baud notu) kaldirildi -> ceviri de yok.
  // Filtre slider etiketlerini (KAPALI/OFF) yeni dile gore tazele
  document.querySelectorAll(".cift-slider").forEach(k => { if (k._ciz) k._ciz(); });
  // Dil butonlari aktiflik
  const bTR = document.getElementById("btnDilTR");
  const bEN = document.getElementById("btnDilEN");
  if (bTR) bTR.classList.toggle("secili", dil === "TR");
  if (bEN) bEN.classList.toggle("secili", dil === "EN");
  // Dinamik alanlari mevcut duruma gore tazele
  if (typeof bagDilTazele === "function") {
    try { bagDilTazele(); } catch(e){}
  }
  if (typeof gcsKartGuncelle === "function") {
    try { gcsKartGuncelle(); } catch(e){}
  }

  // Radar panelini tazele
  if (typeof sonRadar !== "undefined" && typeof radarPaneliGuncelle === "function") {
    try { radarPaneliGuncelle(sonRadar); } catch(e){}
  }
  if (typeof sonRadarHedefler !== "undefined" && typeof radarHedefleriGuncelle === "function") {
    try { radarHedefleriGuncelle(sonRadarHedefler); } catch(e){}
  }
  // Dron kartlarini tazele
  if (typeof sonVeri !== "undefined" && typeof dronKartGuncelle === "function") {
    try {
      for (const sid of Object.keys(sonVeri)) dronKartGuncelle(sonVeri[sid]);
    } catch(e){}
  }
  // Gosterge karuseli etiketlerini tazele
  if (typeof dronKartlar !== "undefined") {
    try {
      for (const sid of Object.keys(dronKartlar)) {
        const k = dronKartlar[sid];
        if (k && typeof k.gosDilTazele === "function") k.gosDilTazele();
      }
    } catch(e){}
  }
  // Rota listesini ve mod gostergesini tazele
  // FAZ18-SIHIRBAZ: sihirbaz kart adlari ve durum metinleri
  // dil degisiminde tazelenir.
  if (typeof window.sitlSihirbazDilDegisti === "function") {
    try { window.sitlSihirbazDilDegisti(); } catch(e){}
  }
  if (typeof window.rotaDilTazele === "function") {
    try { window.rotaDilTazele(); } catch(e){}
  }
  if (typeof window.kameraDilTazele === "function") {
    try { window.kameraDilTazele(); } catch(e){}
  }
  if (typeof window.gorevDilTazele === "function") {
    try { window.gorevDilTazele(); } catch(e){}
  }
  // Harita arama placeholder ve Harita Ayarlari dugme ipucu
  const aramaGiris = document.getElementById("haritaAramaGiris");
  if (aramaGiris && t.aramaPlaceholder) aramaGiris.placeholder = t.aramaPlaceholder;
  const btnHrtAyar = document.getElementById("btnHaritaAyar");
  if (btnHrtAyar && t.btnHaritaAyarIpucu) btnHrtAyar.title = t.btnHaritaAyarIpucu;
  // Terrain dugmesini yeni dile gore tazele
  if (typeof window.terrainBtnTazele === "function") {
    try { window.terrainBtnTazele(); } catch(e){}
  }
  if (typeof window.ikon3dDugmeTazele === "function") {
    try { window.ikon3dDugmeTazele(); } catch(e){}
  }
  // ------------------------------------------------------------
  // v2.4.33: WIDGET DIL TAZELEME
  // ------------------------------------------------------------
  // Widget'larin ICINDEKI dinamik metinler (pusula "DERECE/BAKIS",
  // konum satir etiketleri, sayac dugme ipuclari) `data-i18n` ile
  // isaretli DEGILDIR — JS ile uretildikleri icin yukaridaki
  // querySelectorAll dongusu bunlara dokunmaz. Onceki surumlerde
  // widget modulleri `dilTazele` geri cagrisini TANIMLIYORDU ama
  // BU CAGRI HICBIR YERDEN YAPILMIYORDU; sonuc olarak dil TR<->EN
  // degistiginde widget ic etiketleri eski dilde kaliyordu.
  if (window.Widget && typeof window.Widget.dilTazeleTumu === "function") {
    try { window.Widget.dilTazeleTumu(); } catch(e){}
  }
  // v2.4.33: durum cubugu harita onbellek gostergesi (metni ceviri
  // icerir; JS ile yazildigi icin data-i18n dongusu kapsamaz)
  if (typeof window.hrtCacheDurumDilTazele === "function") {
    try { window.hrtCacheDurumDilTazele(); } catch(e){}
  }
  // v2.4.34: BAGIMSIZ SAYFA TAZELEME KANCALARI (/flight, /video)
  // Bu sayfalarin JS'i panel basliklarini, kamera/dron secim
  // listelerini ve durum metinlerini kendisi uretir; data-i18n
  // dongusu onlara ulasmaz. Ilgili modul yukluyse kendi tazeleme
  // fonksiyonunu saglar.
  if (typeof window.ucusDilTazele === "function") {
    try { window.ucusDilTazele(); } catch(e){}
  }
  // v2.4.44: Yer Istasyonu 2 paneli
  if (typeof window.istasyon2DilTazele === "function") {
    try { window.istasyon2DilTazele(); } catch(e){}
  }
  // v2.4.45: dron kartlarinin altindaki haberlesme konsollari
  if (typeof window.dkKonsolDilTazele === "function") {
    try { window.dkKonsolDilTazele(); } catch(e){}
  }
  if (typeof window.videoDuvarDilTazele === "function") {
    try { window.videoDuvarDilTazele(); } catch(e){}
  }
  // v2.4.51: PostgreSQL kurulum/goc sihirbazi. Perde tamamen JS ile
  // uretilir (data-i18n dongusu ulasmaz) ve GIRIS ONCESI aciktir;
  // kullanici dil dugmesine sihirbaz ekranindayken basabilir.
  if (typeof window.pgSihirbazDilGuncelle === "function") {
    try { window.pgSihirbazDilGuncelle(); } catch(e){}
  }
  /* IS51: panel durum cubugu sayac metinleri (Baglanti Sayisi,
     Rota Sayisi ...) JS ile uretilir; data-i18n dongusu bunlara
     ulasmaz. Dil degisince seritleri yeniden yaz. */
  if (typeof window.panelDurumTazele === "function") {
    try { window.panelDurumTazele(); } catch(e){}
  }
}

// Ikonlu butonlarda metni <span>'a yazar; buton basindaki <i> ikonunu korur.
function butonMetinAyarla(btn, metin){
  const sp = btn.querySelector("span");
  if (sp) sp.textContent = metin;
  else btn.textContent = metin;
}

// v2.4.34: KORUMALI BAGLAMA.
// Eskiden bu iki satir dogrudan `.addEventListener` cagiriyordu ve
// #btnDilTR / #btnDilEN yoksa `null` uzerinde patliyordu. Bu yuzden
// i18n.js YALNIZ index.html'e yuklenebiliyordu; /flight ve /video
// sayfalari sozluge hic erisemedigi icin tamamen Turkce kaliyordu.
// Artik dugmeler yoksa sessizce atlanir ve dosya her sayfada guvenle
// yuklenebilir.
(function(){
  const bTR = document.getElementById("btnDilTR");
  const bEN = document.getElementById("btnDilEN");
  if (bTR) bTR.addEventListener("click", () => applyLanguage("TR", true));
  if (bEN) bEN.addEventListener("click", () => applyLanguage("EN", true));
})();

// v2.4.34: BAGIMSIZ SAYFA DESTEGI (/flight, /video)
// Bu sayfalar kendi WS baglantisini kuran ayri belgelerdir; index.html'in
// baslatma zinciri onlarda calismaz, dolayisiyle applyLanguage hic
// cagrilmaz. `gcs_dil` ayni localStorage anahtari oldugu icin kullanicinin
// komuta ekranindaki dil secimi burada da gecerlidir: sayfa hazir olunca
// secili dili bir kez uygula.
(function(){
  const dilDugmesiVar = document.getElementById("btnDilTR")
                     || document.getElementById("btnDilEN");
  if (dilDugmesiVar) return;  // index.html: kendi baslatma zinciri uygular
  function uygula(){
    try { applyLanguage(aktifDil, false); } catch(e){}
  }
  if (document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", uygula);
  } else {
    uygula();
  }
})();

